/// <summary>
/// /// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METCustTransListingContract</c> contract
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(METCustActivityStatementUIBuilder))
]
class METCustActivityStatementContract extends SrsPrintMgmtContract
{
    boolean             usePrintManagement;
    list                salesTaxCode = new list(Types::String);
    date                toDate, fromDate;
    AccountNum          statementTo;
    SelectableDataArea  selectableDA;

}

